#!/bin/bash
set -euo pipefail

# Docker build & push
APP_NAME="myapp"
VERSION=$(git describe --tags --always)
REGISTRY="ghcr.io/user"

build() {
    echo "🐳 Building $APP_NAME:$VERSION"
    docker build \
        --build-arg VERSION="$VERSION" \
        --build-arg BUILD_DATE="$(date -u +%Y-%m-%dT%H:%M:%SZ)" \
        -t "$REGISTRY/$APP_NAME:$VERSION" \
        -t "$REGISTRY/$APP_NAME:latest" \
        .
}

push() {
    docker push "$REGISTRY/$APP_NAME:$VERSION"
    docker push "$REGISTRY/$APP_NAME:latest"
    echo "✅ Pushed $APP_NAME:$VERSION"
}

# Docker Compose management
dev() {
    docker compose -f docker-compose.yml -f docker-compose.dev.yml up -d
    echo "🚀 Dev environment running"
    docker compose logs -f app
}

prod() {
    docker compose -f docker-compose.yml -f docker-compose.prod.yml up -d
    echo "🚀 Production running"
}

cleanup() {
    docker system prune -af --volumes
    echo "🧹 Cleaned up unused resources"
}

# CI/CD helper
ci_test() {
    docker compose -f docker-compose.test.yml run --rm test
    local EXIT_CODE=$?
    docker compose -f docker-compose.test.yml down -v
    exit $EXIT_CODE
}

# Route command
case "${1:-help}" in
    build) build ;;
    push)  build && push ;;
    dev)   dev ;;
    prod)  prod ;;
    test)  ci_test ;;
    clean) cleanup ;;
    *) echo "Usage: $0 {build|push|dev|prod|test|clean}" ;;
esac

#!/bin/bash
# Production-grade script template
set -euo pipefail
IFS=$"\n\t"

# Constants
readonly SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
readonly LOG_FILE="/var/log/myapp/script.log"

# Argument parsing
VERBOSE=false
DRY_RUN=false
ENV="staging"

usage() {
    cat <<EOF
Usage: $(basename "$0") [OPTIONS] COMMAND

Options:
  -e, --env ENV      Environment (staging|production)
  -v, --verbose      Verbose output
  -n, --dry-run      Show what would be done
  -h, --help         Show this help

Commands:
  deploy    Deploy application
  rollback  Rollback to previous version
  status    Show current status
EOF
}

while [[ $# -gt 0 ]]; do
    case "$1" in
        -e|--env)     ENV="$2"; shift 2 ;;
        -v|--verbose) VERBOSE=true; shift ;;
        -n|--dry-run) DRY_RUN=true; shift ;;
        -h|--help)    usage; exit 0 ;;
        -*)           echo "Unknown: $1"; usage; exit 1 ;;
        *)            COMMAND="$1"; shift ;;
    esac
done

# Logging
log() {
    local level="$1"; shift
    local msg="$*"
    local ts=$(date "+%Y-%m-%d %H:%M:%S")
    echo "[$ts] [$level] $msg" | tee -a "$LOG_FILE"
}
info()  { log "INFO" "$@"; }
warn()  { log "WARN" "$@"; }
error() { log "ERROR" "$@"; }

# Main
main() {
    info "Starting ${COMMAND:-unknown} on $ENV"
    case "${COMMAND:-}" in
        deploy)   do_deploy ;;
        rollback) do_rollback ;;
        status)   do_status ;;
        *)        usage; exit 1 ;;
    esac
    info "Completed successfully"
}

main "$@"
